<template>
  <v-card dark class="plugin-LinkEndpointToControlPoint">
    <v-layout pa-3 class="plugin-LinkEndpointToControlPoint-layout">
      <v-flex class="plugin-LinkEndpointToControlPoint-flex spinal-scrollbar">
        <v-treeview
          :items="treeData"
          :open.sync="treeOpened"
          dark
          hoverable
          selectable
          transition
          v-model="treeSelection"
          :load-children="openChildren"
        >
          <template v-slot:append="{ item }">
            <v-btn
              v-tooltip="'Open in Node Inspector Viewer'"
              icon
              small
              :href="`/html/graph-inspector/?id=${item.servId}`"
              target="_blank"
            >
              <v-icon>workspaces_outline</v-icon>
            </v-btn>
          </template>
        </v-treeview>
      </v-flex>
      <v-flex
        class="plugin-LinkEndpointToControlPoint-flex spinal-scrollbar plugin-LinkEndpointToControlPoint-controls"
      >
        <v-text-field
          v-model="cpProfileName"
          label="Control Point profile name"
          required
        ></v-text-field>
        <v-text-field v-model="cpFilterPattern" :label="cpFilterLabel" required>
          <template v-slot:append>
            <v-checkbox
              v-model="useCPRegexp"
              label="RegExp"
              hide-details
            ></v-checkbox>
          </template>
        </v-text-field>
        <v-divider class="my-2"></v-divider>
        <v-text-field
          v-model="endpointFilterRegexpPattern"
          label="Endpoint filter RegExp pattern"
          required
        ></v-text-field>
        <v-btn
          :disabled="disableStart"
          @click="startLink"
          :loading="loadingLink"
          >Start</v-btn
        >
      </v-flex>
    </v-layout>
  </v-card>
</template>

<script>
import { getNodeByServerId } from './utils/getNodeByServerId';
import { StartLinkTSEndpointToCP } from './utils/StartLinkTSEndpointToCP';

export default {
  name: 'LinkEndpointTimeseriesToControlPoint',
  data() {
    return {
      nodeId: 0,
      contextId: 0,
      treeData: [],
      treeOpened: [],
      treeSelection: [],
      cpProfileName: '',
      cpFilterPattern: '',
      useCPRegexp: false,
      endpointFilterRegexpPattern: '',
      loadingLink: false,
    };
  },
  methods: {
    async opened(option) {
      this.nodeId = option.nodeId;
      this.contextId = option.contextId;
      const node = getNodeByServerId(this.nodeId);
      const context = getNodeByServerId(this.contextId);
      console.log('opened node', node, this.nodeId);
      console.log('opened context', context, this.contextId);
      const treeNode = {
        id: node._server_id.toString(),
        servId: node._server_id,
        name: node.getName().get(),
        depth: 0,
        children: [],
      };
      this.treeData = [treeNode];
    },
    async openChildren(item) {
      const node = getNodeByServerId(item.servId);
      const context = getNodeByServerId(this.contextId);
      const children = await node.getChildrenInContext(context);
      const childTreeNodes = [];
      for (const child of children) {
        const childTreeNode = {
          id: item.id + '.' + child._server_id.toString(),
          servId: child._server_id,
          name: child.getName().get(),
          depth: item.depth + 1,
        };
        const childNodeType = child.info.type.get();
        if (
          childNodeType.endsWith('Category') ||
          childNodeType.endsWith('Group')
        ) {
          childTreeNode.children = [];
        }
        childTreeNodes.push(childTreeNode);
      }
      if (childTreeNodes.length === 0) return;
      item.children = childTreeNodes;
      return childTreeNodes;
    },
    async startLink() {
      this.loadingLink = true;
      try {
        await StartLinkTSEndpointToCP(
          this.treeSelection,
          getNodeByServerId(this.contextId),
          this.cpProfileName,
          this.cpFilterPattern,
          this.useCPRegexp,
          this.endpointFilterRegexpPattern
        );
      } catch (error) {
        this.loadingLink = false;
        console.error('Error during linking process', error);
        return;
      }
      this.loadingLink = false;
    },
    closed: function () {},
    removed: function () {},
  },
  computed: {
    cpFilterLabel() {
      return this.useCPRegexp
        ? 'Control Point profile RegExp'
        : 'Control Point profile exact name';
    },
    disableStart() {
      return (
        this.treeSelection.length === 0 ||
        this.cpProfileName.trim() === '' ||
        this.cpFilterPattern.trim() === '' ||
        this.endpointFilterRegexpPattern.trim() === ''
      );
    },
  },
};
</script>

