import { getNodeByServerId } from './getNodeByServerId';
import {
  getSpinalTimeSerieInst,
} from './SpinalTimeSerieInst';
import { SpinalGraphService } from 'spinal-env-viewer-graph-service';

const NODE_HAS_CP_RELATIONTION_NAME = 'hasControlPoints';
const CP_HAS_EP_RELATIONTION_NAME = 'hasBmsEndpoint';
const NODE_FIND_EP_RELATIONTIONS_NAME = [
  'hasBmsDevice',
  'hasBmsEndpoint',
  'hasBmsEndpointGroup'
];
const HAS_TIME_SERIES_RELATIONTION_NAME = 'hasTimeSeries';

export async function StartLinkTSEndpointToCP(
  ids,
  context,
  cpProfileName,
  cpFilterPattern,
  useCPRegexp,
  endpointFilterRegexpPattern
) {
  const nodes = await loadNodeLeafFromIds(ids, context);
  console.log('leafNodes loaded', nodes);

  for (let i = 0; i < nodes.length; i += 30) {
    const chunk = nodes.slice(i, i + 30);
    await Promise.all(
      chunk.map(async (node, idx) => {
        const globalIdx = i + idx;
        console.log(globalIdx + 1, '/', nodes.length);
        try {
          // load endpoints and control points in parallel
          const [
            { epTimeSeries, epTsNode },
            { cpEpTs, cpEpTsNode, cpMatchingEndpoint },
          ] = await Promise.all([
            handleLoadEP(node, endpointFilterRegexpPattern),
            handleLoadCP(node, cpProfileName, cpFilterPattern, useCPRegexp),
          ]);
          if (cpEpTs) {
            // time series is already linked to control point endpoint
            if (cpEpTs !== epTimeSeries) {
              // time series linked to control point endpoint is different from endpoint time series
              // remove existing link
              await cpMatchingEndpoint.removeChild(
                cpEpTsNode,
                HAS_TIME_SERIES_RELATIONTION_NAME,
                'PtrLst'
              );
              await cpMatchingEndpoint.addChild(
                epTsNode,
                HAS_TIME_SERIES_RELATIONTION_NAME,
                'PtrLst'
              );
            }
            // else time series is already linked, do nothing
          } else {
            // create epTsNode node to link time series
            await cpMatchingEndpoint.addChild(
              epTsNode,
              HAS_TIME_SERIES_RELATIONTION_NAME,
              'PtrLst'
            );
          }
        } catch (error) {
          console.error(error);
        }
      })
    );
  }
}

async function getEndpoint(node, endpointFilterRegexpPattern) {
  const regex = new RegExp(endpointFilterRegexpPattern);
  for await (const item of node.visitChildren(NODE_FIND_EP_RELATIONTIONS_NAME)) {
    const name = item.info.name.get();
    if (regex.test(name)) {
      return item;
    }
  }
}

async function handleLoadEP(
  node,
  endpointFilterRegexpPattern
) {
  const endpoint = await getEndpoint(node, endpointFilterRegexpPattern);
  if (endpoint === undefined) {
    throw new Error(
      `no endpoint matching filter ${endpointFilterRegexpPattern} for node [${node._server_id
      }] ${node.info.name.get()}`
    );
  }
  const tsService = getSpinalTimeSerieInst();
  SpinalGraphService._addNode(endpoint);
  const epTimeSeries = await tsService.getOrCreateTimeSeries(
    endpoint.info.id.get()
  );
  const tsNodes = await endpoint.getChildren([
    HAS_TIME_SERIES_RELATIONTION_NAME,
  ]);
  return { epTimeSeries, epTsNode: tsNodes[0] };
}

async function handleLoadCP(
  node,
  cpProfileName,
  cpFilterPattern,
  useCPRegexp
) {
  const controlPoints = await node.getChildren([NODE_HAS_CP_RELATIONTION_NAME]);
  const matchingCP = controlPoints.find((cp) => {
    const profileName = cp.info.name.get();
    return cpProfileName === profileName;
  });
  if (matchingCP === undefined) {
    throw new Error(
      `no control point matching profile name ${cpProfileName} for node [${node._server_id
      }] ${node.info.name.get()}`
    );
  }
  // load endpoints of control point
  const cpEndpoints = await matchingCP.getChildren([
    CP_HAS_EP_RELATIONTION_NAME,
  ]);
  const cpMatchingEndpoint = cpEndpoints.find((ep) => {
    const name = ep.info.name.get();
    const regex = new RegExp(cpFilterPattern);
    return useCPRegexp ? regex.test(name) : name === cpFilterPattern;
  });
  if (cpMatchingEndpoint === undefined) {
    throw new Error(
      `no control point endpoint matching filter ${cpFilterPattern} for control point [${matchingCP._server_id
      }] ${matchingCP.info.name.get()}`
    );
  }
  // test if time series are already linked to control point endpoint
  const existingTSEndpoints = await cpMatchingEndpoint.getChildren([
    HAS_TIME_SERIES_RELATIONTION_NAME,
  ]);
  const cpEpTsNode = existingTSEndpoints[0];
  if (!cpEpTsNode) {
    return { cpEpTs: null, cpEpTsNode: null, cpMatchingEndpoint };
  }

  return {
    cpEpTs: (await cpEpTsNode.getElement(true)),
    cpEpTsNode,
    cpMatchingEndpoint,
  };
}

async function loadNodeLeafFromIds(
  ids,
  context
) {
  const startingNodes = ids
    .map((id) => {
      const ids = id.split('.');
      const idString = ids[ids.length - 1];
      const servId = parseInt(idString, 10);
      return getNodeByServerId(servId);
    })
    .filter((node) => node !== undefined);
  const nodes = [];

  const getChildrenRec = async (node, res) => {
    const nodeType = node.info.type.get();
    if (
      nodeType.endsWith('GroupContext') ||
      nodeType.endsWith('Category') ||
      nodeType.endsWith('Group')
    ) {
      const children = await node.getChildrenInContext(context);
      for (const child of children) {
        await getChildrenRec(child, res);
      }
    } else {
      res.push(node);
    }
  };
  for (let i = 0; i < startingNodes.length; i += 20) {
    console.log(
      `loading leaf nodes ${i} to ${i + 20} / ${startingNodes.length}`
    );
    const chunk = startingNodes.slice(i, i + 20);
    await Promise.all(chunk.map((node) => getChildrenRec(node, nodes)));
  }

  return nodes;
}
