import {
  SpinalContextApp,
  spinalContextMenuService,
} from 'spinal-env-viewer-context-menu-service';
import {
  spinalPanelManagerService,
} from 'spinal-env-viewer-panel-manager-service';
import {
  SpinalGraphService,
} from 'spinal-env-viewer-graph-service';

export default class SpinalLinkerButton extends SpinalContextApp {
  constructor() {
    super('Link Endpoint Timeseries to Control Point', 'Open Link Endpoint Timeseries to Control Point', {
      icon: 'timeline',
      icon_type: 'in',
      backgroundColor: '#000000',
      fontColor: '#ffffff',
    });
  }

  isShown(option) {
    let selectedContext = option.context;
    if (option.context) {
      selectedContext = SpinalGraphService.getRealNode(option.context.id.get());
      return selectedContext.info.type.get().endsWith('GroupContext') ? Promise.resolve(true) : Promise.resolve(-1);
    }
    return Promise.resolve(-1);
  }

  action(option) {
    const param = {
      nodeId: SpinalGraphService.getRealNode(option.selectedNode.id.get())._server_id,
      contextId: SpinalGraphService.getRealNode(option.context.id.get())._server_id,
    };
    spinalPanelManagerService.openPanel('plugin-link_endpoint_timeseries_to_control_point', param);
  }
}

const barName = 'GraphManagerSideBar';

spinalContextMenuService.registerApp(barName, new SpinalLinkerButton(), [3]);
